args.script:
awk '
{
    name = $1
    action = $2
    stock_idx = $3
    if (name == "Bob") {
        if (action == "Purchase") {
            bought[stock_idx] = 1
        }
        if (action == "Sell") {
            sold[stock_idx] = 1
        }
    }
}
END {
    count = 0
    for (s in sold) {
        if (!(s in bought)) {
            count++
        }
    }
    print count
}
' /usr/stock.log
